// ---------------------------------------------------------------- fetch mocking

/**
 * Swap in global fetch for the duration of a test (zero network). Records every
 * call's URL + init; handler returns a Response (or promise of one).
 */
export function mockFetch(handler: (url: string, init: RequestInit | undefined) => Response | Promise<Response>): {
  calls: Array<{ url: string; init: RequestInit | undefined }>;
  restore(): void;
} {
  const original = globalThis.fetch;
  const calls: Array<{ url: string; init: RequestInit | undefined }> = [];
  globalThis.fetch = ((input: RequestInfo | URL, init?: RequestInit) => {
    const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
    calls.push({ url, init });
    return handler(url, init);
  }) as typeof fetch;
  return { calls, restore: () => void (globalThis.fetch = original) };
}

/** Response with JSON body + repeated set-cookie headers (Bun supports array pairs). */
export function jsonResponse(body: unknown, setCookies: string[] = [], status = 200): Response {
  const headers: HeadersInit = setCookies.map((cookie) => ["set-cookie", cookie] as [string, string]);
  return new Response(JSON.stringify(body), { status, headers });
}

